import re
seq = ""
with open("region.fasta") as f:
    for line in f:
        line=line.strip()
        if line.startswith(">"): continue
        seq += line
n=len(seq)
def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

def hairpin_starting_at(s,i,min_stem=4,max_loop=14):
    # returns True if a hairpin stem starts at i (stem>=min_stem, loop<=max_loop)
    L=len(s)
    for stem in range(min_stem,15):
        left=s[i:i+stem]
        if len(left)<stem: return False
        rc=revcomp(left)
        for loop in range(3,max_loop+1):
            j=i+stem+loop
            if j+stem>L: break
            if s[j:j+stem]==rc:
                return True,(stem,loop,left)
    return False,None

def hairpin_in(s,a,b,min_stem=4,max_loop=14):
    for i in range(a,b):
        ok,info=hairpin_starting_at(s,i,min_stem,max_loop)
        if ok: return True,(i,info)
    return False,None

